package com.bank.core;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.*;

public class ConstantHashCodeDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int n = 20000;

        Map<ConstantHashAccount, Integer> bad = new HashMap<>();
        for (int i = 0; i < n; i++) bad.put(new ConstantHashAccount("SAV" + i), i);
        long t0 = System.nanoTime();
        for (int i = 0; i < n; i++) bad.get(new ConstantHashAccount("SAV" + i));
        long badMs = (System.nanoTime() - t0) / 1_000_000;
        log.warning(() -> "Constant hashCode: " + n + " lookups took " + badMs + " ms (O(n) per lookup)");

        Map<SpreadHashAccount, Integer> good = new HashMap<>();
        for (int i = 0; i < n; i++) good.put(new SpreadHashAccount("SAV" + i), i);
        long t1 = System.nanoTime();
        for (int i = 0; i < n; i++) good.get(new SpreadHashAccount("SAV" + i));
        long goodMs = (System.nanoTime() - t1) / 1_000_000;
        log.info(() -> "Spread hashCode: " + n + " lookups took " + goodMs + " ms (O(1) per lookup)");

        // Correctness is identical for both — only speed differs.
        log.info(() -> "Correctness check (spread) get SAV5 → " + good.get(new SpreadHashAccount("SAV5")));
    }
}
